'use strict';
const $=selector=>document.querySelector(selector);
const escapeHTML=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const EXTENSION=typeof A1_EXTENSION==='undefined'?{units:[],challenges:[],words:[]}:A1_EXTENSION;
const NEXT=typeof NEXT_LESSONS==='undefined'?{units:[],challenges:[],words:[]}:NEXT_LESSONS;
const A2=typeof COURSE_A2==='undefined'?{units:[],challenges:[],words:[]}:COURSE_A2;
const A2PLUS=typeof COURSE_A2PLUS==='undefined'?{units:[],challenges:[],words:[]}:COURSE_A2PLUS;
const B1=typeof COURSE_B1==='undefined'?{units:[],challenges:[],words:[]}:COURSE_B1;
const MAP=typeof COURSE_MAP==='undefined'?{modules:[],sources:[],limitations:[]}:COURSE_MAP;
const BASE_UNITS=[...UNITS,...(EXTENSION.units||[]),...(NEXT.units||[]),...(A2.units||[]),...(A2PLUS.units||[]),...(B1.units||[])],MORE_UNITS=[...CHALLENGE_UNITS,...(EXTENSION.challenges||[]),...(NEXT.challenges||[]),...(A2.challenges||[]),...(A2PLUS.challenges||[]),...(B1.challenges||[])];
const mathCourse = typeof MATH_COURSE === 'undefined' ? { units: [], words: [] } : MATH_COURSE;
const pathLabels = {base:'Grunnløp', challenge:'Mer utfordring', math:'Matematikk på norsk'};
const ALL_UNITS=[...BASE_UNITS.map(u=>({...u,path:'base'})),...MORE_UNITS.map(u=>({...u,path:'challenge'})),...mathCourse.units];
const ALL_WORDS=[...GLOSSARY,...(EXTENSION.words||[]),...(NEXT.words||[]),...(A2.words||[]),...(A2PLUS.words||[]),...(B1.words||[]),...mathCourse.words];
const ALL_LESSONS=ALL_UNITS.flatMap(unit=>unit.lessons.map(lesson=>({...lesson,unitId:unit.id,path:unit.path})));
const activeUnits=()=>ALL_UNITS.filter(u=>u.path===state.selectedPath);
const pathLessons=()=>ALL_LESSONS.filter(l=>l.path===state.selectedPath);
const KEY='sprakverkstedet-a0-a1-v2';
let state={done:{},drafts:{},last:null,support:true,translations:true,free:[]},oldWork=null,canStore=true;
try{const saved=JSON.parse(localStorage.getItem(KEY)||'null');if(saved&&typeof saved==='object'){state={...state,...saved};if(!state.done||typeof state.done!=='object'||Array.isArray(state.done))state.done={};if(!state.drafts||typeof state.drafts!=='object'||Array.isArray(state.drafts))state.drafts={};if(!Array.isArray(state.free))state.free=[];}oldWork=JSON.parse(localStorage.getItem('sprakverkstedet-v1')||'null');}catch{canStore=false;}
for(const [id,draft] of Object.entries(state.drafts)){if(!draft||typeof draft!=='object'||typeof draft.text!=='string'){state.drafts[id]={text:'',checks:[]};}else{draft.checks=Array.isArray(draft.checks)?draft.checks.filter(Number.isInteger):[];}}
state.free=state.free.filter(text=>typeof text==='string');
state.support=state.support!==false;state.translations=state.translations!==false;
state.generalPath=state.selectedPath==='challenge'||(state.selectedPath==='math'&&state.generalPath==='challenge')?'challenge':'base';
state.selectedPath=state.generalPath;
if(!state.lastByPath||typeof state.lastByPath!=='object'||Array.isArray(state.lastByPath))state.lastByPath={};
if(typeof state.last==='string'&&!state.lastByPath.base&&ALL_LESSONS.some(l=>l.id===state.last&&l.path==='base'))state.lastByPath.base=state.last;
if(!state.rounds||typeof state.rounds!=='object'||Array.isArray(state.rounds))state.rounds={};
if(!state.visited||typeof state.visited!=='object'||Array.isArray(state.visited))state.visited={};
if(!state.activities||typeof state.activities!=='object'||Array.isArray(state.activities))state.activities={};
if(!state.learning||typeof state.learning!=='object'||!state.learning.records||typeof state.learning.records!=='object'||Array.isArray(state.learning.records))state.learning=LearningEngine.createState();
let current=null,view='home',choice=null,selected=[],feedback=null,hint=false,inputValue='',freeCategory='all',customTokens=[],assisted=false,showModel=false,repeatQueue=[],repeatMode=false,repeatExtra=false,submittedCorrect=false;
function taskKey(task){return `${task.skill||({choice:'recognition',input:'recall',build:'construction'}[task.type]||'exposure')}:${task.targetKey||task.id}`;}
function materialize(base,index){const variants=Array.isArray(base.variants)&&base.variants.length?base.variants:[{}],variant=variants[index%variants.length],task={...base,...variant,id:base.id,unitId:base.unitId};if(task.options){const options=[...task.options];let seed=(index+1)*7919+base.id.split('').reduce((a,c)=>a+c.charCodeAt(0),0);for(let i=options.length-1;i>0;i--){seed=(seed*16807)%2147483647;const j=seed%(i+1);[options[i],options[j]]=[options[j],options[i]];}task.options=options;}return task;}
function openVariant(base,index,opts={}){current=materialize(base,index);view='lesson';resetTask();assisted=false;showModel=false;if(base.path==='math' && state.selectedPath!=='math')state.generalPath=state.selectedPath;state.selectedPath=base.path;state.visited[base.id]=true;state.last=base.id;state.lastByPath[base.path]=base.id;persist();if(opts.route!==false)updateRoute(base.id);render();if(matchMedia('(max-width:780px)').matches)$('#chapterMenu').open=false;if(opts.focus!==false){$('#main').focus({preventScroll:true});$('#main').scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'});}}
function allRecallVariants(){return pathLessons().filter(l=>l.type==='input'&&(l.skill==='recall'||state.selectedPath==='challenge'&&l.skill==='construction')).flatMap(l=>(Array.isArray(l.variants)&&l.variants.length?l.variants:[{}]).map((v,index)=>({base:l,index,task:{...l,...v}})));}
function repeatCandidates(now=Date.now()){const due=new Set(LearningEngine.dueKeys(state.learning,now)),all=allRecallVariants().filter(x=>(state.learning.records[taskKey(x.task)]?.attemptsCount||0)>0),unique=[...new Map(all.map(x=>[taskKey(x.task),x])).values()];return {unique,dueItems:unique.filter(x=>due.has(taskKey(x.task))),extras:unique.filter(x=>!due.has(taskKey(x.task)))};}
function startRepeat(){const {unique,dueItems,extras}=repeatCandidates();if(unique.length<3){repeatMode=false;view='repeat';current=null;render();return;}repeatQueue=[...dueItems,...extras];repeatExtra=!dueItems.length;repeatMode=true;openVariant(repeatQueue[0].base,repeatQueue[0].index);}

function nextRepeat(){if(!repeatQueue.length)return;repeatQueue.push(repeatQueue.shift());const x=repeatQueue[0];repeatExtra=!new Set(LearningEngine.dueKeys(state.learning,Date.now())).has(taskKey(x.task));openVariant(x.base,x.index);}
function markAssisted(){if(submittedCorrect||assisted)return;assisted=true;if(!current||!['choice','input','build'].includes(current.type))return;const skill=current.skill||({choice:'recognition',input:'recall',build:'construction'}[current.type]);state.learning=LearningEngine.recordHelp(state.learning,{key:taskKey(current),lessonId:current.id,skill,now:Date.now()});persist();}
function recordAttempt(correct){if(!['choice','input','build'].includes(current.type))return;state.learning=LearningEngine.recordAttempt(state.learning,{key:taskKey(current),lessonId:current.id,skill:current.skill||({choice:'recognition',input:'recall',build:'construction'}[current.type]),correct,assisted,now:Date.now()});persist();}
function correctForm(){if(current.type==='choice')return current.options.find(o=>o.id===current.correct)?.label||'';if(current.type==='build')return current.answer.join(' ');if(current.type==='input')return [current.before,current.accepted?.[0],current.after].filter(Boolean).join(' ').replace(/\s+([.!?])/g,'$1');return '';}

const FREE_GROUPS=[{id:'who',label:'Hvem',tokens:['Jeg','Du','Vi','Anna','Mali','Boka']},{id:'verb',label:'Gjør',tokens:['heter','har','er','leser','skriver','spiser','skal','lese','skrive','går på skolen']},{id:'more',label:'Mer',tokens:['en bok','en penn','en stol','et bord','på skolen','på bordet','under bordet','i sekken','i morgen','på mandag','på tirsdag','klokka åtte','klokka tolv','klokka seks','og']}];
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{canStore=false;storageNotice();}}
function migrateOldWork(){if(!Array.isArray(state.archivedDone))state.archivedDone=[];let changed=false;for(const lesson of ALL_LESSONS){if(!Object.prototype.hasOwnProperty.call(state.done,lesson.id))continue;const entry=state.done[lesson.id];if(!entry||entry.kind!==lesson.type){state.archivedDone.push({id:lesson.id,record:entry});delete state.done[lesson.id];changed=true;}}if(changed)persist();}
migrateOldWork();
function storageNotice(){if(!$('#storageWarning')){const notice=document.createElement('div');notice.id='storageWarning';notice.className='storage-warning';notice.textContent='Nettleseren kan ikke lagre nå. Arbeidet blir her mens siden er åpen.';$('.masthead').after(notice);}}
function announce(message){$('#announcer').textContent='';requestAnimationFrame(()=>$('#announcer').textContent=message);}
function unitFor(lesson=current){return ALL_UNITS.find(u=>u.id===lesson?.unitId);}
function completedCount(unit){return unit.lessons.filter(l=>state.done[l.id]).length;}
function totalDone(){return pathLessons().filter(l=>state.done[l.id]).length;}
function normalized(text){return text.normalize('NFC').trim().toLocaleLowerCase('nb').replace(/[.!?]+$/,'').replace(/\s+/g,' ');}
function learningText(text){return escapeHTML(text).replace(/([.!?])\s+(?=[A-ZÆØÅ])/g,'$1<br>');}
function wordCount(text){return text.trim()?text.trim().split(/\s+/).length:0;}
function textOfTokens(){const text=selected.map(t=>t.text).join(' ');return text+(view==='free'||current?.sentence?'.':'');}
function suggested(){const lessons=pathLessons(),last=state.lastByPath[state.selectedPath],index=lessons.findIndex(l=>l.id===last);if(index>=0&&!state.done[last])return lessons[index];if(index>=0)return lessons.slice(index+1).find(l=>!state.done[l.id])||lessons.slice(0,index+1).find(l=>!state.done[l.id])||lessons[index];return lessons.find(l=>!state.done[l.id])||lessons[0];}
function a0Suggested(){const lessons=pathLessons().filter(l=>unitFor(l)?.stage==='a0');return lessons.find(l=>!state.done[l.id])||lessons[0];}
function repeatPanel(){const {unique,dueItems}=repeatCandidates();const label=state.selectedPath==='challenge'?'Repeter korte svar':'Repeter';const text=unique.length<3?'Prøv flere ulike svar først.':dueItems.length?`${dueItems.length} korte svar er klare for repetisjon.`:'Ingen svar er klare ennå. Du kan ta ekstraøving.';return `<section class="repeat-panel"><div><strong>${label}</strong><p>${text}</p></div><button class="quiet" data-repeat="true">${unique.length<3?'Velg oppgaver':dueItems.length?'Start repetisjon':'Start ekstraøving'} →</button></section>`;}

function updateRoute(route){if(location.hash.slice(1)!==route)history.pushState(null,'','#'+route);}
function resetTask(){choice=null;selected=[];feedback=null;hint=false;inputValue='';submittedCorrect=false;}
function openLesson(id,opts={}){const lesson=ALL_LESSONS.find(l=>l.id===id);if(!lesson)return;repeatMode=false;const index=Number.isInteger(state.rounds[id])?state.rounds[id]:0;state.rounds[id]=index+1;openVariant(lesson,index,opts);}
function leaveMath(){if(state.selectedPath==='math'){state.selectedPath=state.generalPath==='challenge'?'challenge':'base';persist();}}
function openHome(route=true){leaveMath();repeatMode=false;view='home';current=null;resetTask();if(route)updateRoute(state.selectedPath==='challenge'?'utfordring':'oversikt');render();$('#main').focus({preventScroll:true});}
function openCourse(route=true){leaveMath();repeatMode=false;view='course';current=null;resetTask();if(route)updateRoute('kurs');render();$('#main').focus({preventScroll:true});}
function openFree(route=true){view='free';current=null;resetTask();if(route)updateRoute('fri');render();if(matchMedia('(max-width:780px)').matches)$('#chapterMenu').open=false;$('#main').focus({preventScroll:true});}
const PHASES=[{id:'a0',title:'A0',nav:'Fra start · A0',sub:'Bilder og<br>enkeltord'},{id:'bridge',title:'På vei',nav:'Ord blir setninger',sub:'Små<br>setninger'},{id:'a1',title:'A1',nav:'Bruk språket · A1',sub:'Les og skriv<br>om hverdagen'},{id:'a1plus',title:'Videre · mot A2',nav:'Videre · mot A2',sub:'Mer språk<br>i hverdagen'},{id:'a2',title:'A2 · grunnlag',nav:'A2 · grunnlag',sub:''},{id:'a2plus',title:'A2 · videre',nav:'A2 · videre',sub:''},{id:'b1',title:'Mot B1',nav:'Mot B1',sub:''}];
function navHTML(){if(state.selectedPath==='math')return mathNavHTML()+activeUnits().map(u=>`<button class="chapter-link ${current?.unitId===u.id?'current':''}" data-unit="${u.id}"><span class="chapter-num">${u.number}</span>${escapeHTML(u.title)}${completedCount(u)===u.lessons.length?' ✓':''}</button>`).join('');return `<button class="quiet course-nav-link" data-course="true">Kursoversikt ↗</button>`+(mathCourse.units.length?mathNavHTML():'')+PHASES.map(phase=>{const units=activeUnits().filter(u=>u.stage===phase.id);if(!units.length)return '';return `<details class="sidebar-phase" ${current&&unitFor()?.stage===phase.id?'open':''}><summary>${phase.nav}</summary>${units.map(u=>`<button class="chapter-link ${current?.unitId===u.id?'current':''}" data-unit="${u.id}" ${current?.unitId===u.id?'aria-current="true"':''}><span class="chapter-num">${u.number}</span><span>${escapeHTML(u.title)}</span>${completedCount(u)===u.lessons.length?'<span class="chapter-complete" aria-label="Alle øvelser gjort">✓</span>':''}</button>`).join('')}</details>`;}).join('')+`<div class="free-entry"><button class="quiet" id="repeatButton">${state.selectedPath==='challenge'?'Repeter korte svar':'Repeter'} ↗</button><button class="quiet" id="freeButton">Bygg fritt ↗</button><p>Dine egne ord og setninger.</p></div>`;}

function render(){
 $('#chapterNav').innerHTML=navHTML();$('#overviewButton').setAttribute('aria-current',view==='home'?'page':'false');
 if(view==='math')$('#view').innerHTML=mathHubHTML();else if(view==='home')renderHome();else if(view==='free')renderFree();else if(view==='repeat')renderRepeat();else if(view==='course')renderCourse();else renderLesson();
 document.title=view==='math'?'Matematikk på norsk · Språkverkstedet':view==='lesson'?`${current.title} · Språkverkstedet`:view==='free'?'Bygg fritt · Språkverkstedet':'Språkverkstedet · Norsk fra start';
}
function mathEntry(){return mathCourse.units.length?`<section class="math-entry"><div><strong>Matematikk på norsk</strong><p>Lær å lese oppgaver og forklare hvordan du regner.</p></div><button data-math="true">Åpne matematikksporet</button></section>`:'';}
function pathSelector(){return mathEntry()+ `<section class="path-picker" aria-label="Velg vei"><h2>Velg hvordan du vil øve</h2><div class="path-options"><button class="path-option ${state.selectedPath==='base'?'selected':''}" data-path="base" aria-pressed="${state.selectedPath==='base'}"><strong>Grunnløp</strong><span>Små steg og øving.</span></button><button class="path-option ${state.selectedPath==='challenge'?'selected':''}" data-path="challenge" aria-pressed="${state.selectedPath==='challenge'}"><strong>Mer utfordring</strong><span>Flere opplysninger, rette avvik og egne korte svar.</span></button></div><p>Du kan bytte vei når du vil. Arbeidet ditt blir beholdt.</p></section>`;}
function switchPath(path){if(path!=='base'&&path!=='challenge')return;const previous=current&&unitFor(),other=path==='challenge'?MORE_UNITS.find(u=>u.baseUnitId===(previous?.baseUnitId||previous?.id)):BASE_UNITS.find(u=>u.id===(previous?.baseUnitId||previous?.id));state.selectedPath=path;persist();if(view==='course'){openCourse();return;}if(view==='lesson'&&other){const last=other.lessons.find(l=>l.id===state.lastByPath[path]);const lesson=last||other.lessons.find(l=>!state.done[l.id])||other.lessons[0];openLesson(lesson.id);}else openHome();}
function unitStatus(unit){const done=completedCount(unit);if(done===unit.lessons.length)return 'Gjort';const worked=unit.lessons.some(l=>state.done[l.id]||state.visited[l.id]||state.rounds[l.id]>0||state.drafts[l.id]?.text?.trim()||Object.values(state.lastByPath).includes(l.id)||Object.values(state.learning.records).some(r=>r?.lessonId===l.id));return worked?'Påbegynt':'Ikke startet';}
function phaseStats(stage){const units=activeUnits().filter(u=>u.stage===stage),total=units.reduce((n,u)=>n+u.lessons.length,0),done=units.reduce((n,u)=>n+completedCount(u),0),complete=units.filter(u=>completedCount(u)===u.lessons.length).length;return {total,done,complete,units:units.length};}
function courseProgress(unit){const done=totalDone(),total=pathLessons().length;return `<section class="course-progress" aria-label="Din framgang"><div class="progress-heading"><h2>Din framgang</h2><strong>${done} av ${total} øvelser gjort</strong></div><progress max="${total}" value="${done}" aria-label="Øvelser gjort i denne veien">${done} av ${total}</progress><p>Dette viser arbeid du har gjort. Det er ikke en nivåprøve.</p><button class="quiet" data-course="true">Se moduler og temaer →</button></section>`;}
function modules(){return Array.isArray(MAP.modules)?MAP.modules:[];}
function moduleFor(unit){const id=unit?.baseUnitId||unit?.id;return modules().find(m=>Array.isArray(m.unitIds)&&m.unitIds.includes(id));}
function moduleUnits(module){const ids=Array.isArray(module.unitIds)?module.unitIds:[];return ids.map(id=>activeUnits().find(u=>(u.baseUnitId||u.id)===id)).filter(Boolean);}
function moduleStats(module){const units=moduleUnits(module);return {units,done:units.reduce((n,u)=>n+completedCount(u),0),total:units.reduce((n,u)=>n+u.lessons.length,0)};}
function moduleNext(module){const units=moduleUnits(module),lessons=units.flatMap(u=>u.lessons),last=lessons.find(l=>l.id===state.lastByPath[state.selectedPath]&&!state.done[l.id]);return last||lessons.find(l=>!state.done[l.id])||lessons[0];}
function listText(value){return Array.isArray(value)?value:typeof value==='string'?[value]:[];}
function activityHTML(module){const a=module.teacherActivity;if(!a||typeof a!=='object')return '';const script=listText(a.teacherScript),checklist=listText(a.checklist);return `<details class="teacher-activity"><summary>Til læreren · frivillig muntlig eller lytteaktivitet</summary><p>Dette er en klasseromsaktivitet ledet av lærer. Nettstedet spiller ikke av lyd og vurderer ikke uttale eller lytting.</p><p>${escapeHTML(a.instruction||'')}</p>${script.length?`<h4>Lærerskript</h4>${script.map(t=>`<p>${escapeHTML(t)}</p>`).join('')}`:''}${checklist.length?`<h4>Forslag til gjennomføring</h4><ul>${checklist.map(t=>`<li>${escapeHTML(t)}</li>`).join('')}</ul>`:''}<label><input type="checkbox" data-activity="${escapeHTML(module.id)}" ${state.activities[module.id]===true?'checked':''}> Jeg har deltatt i aktiviteten</label><p>Dette er din egen registrering og teller ikke som fullført øvelse eller mestring.</p></details>`;}
function renderCourse(){const currentUnit=unitFor(suggested());$('#view').innerHTML=`<header class="course-title"><span class="eyebrow">KURSOVERSIKT</span><h1>Modulært norskkurs · A0 mot B1</h1><p>${escapeHTML(MAP.scope||'Velg en modul eller et tema. Du kan åpne alle oppgavene når du vil.')}</p><p class="course-limits">Kursmodulene er pedagogiske grupper i dette kurset. Fullførte øvelser dokumenterer ikke et oppnådd språknivå.</p><details><summary>Les om avgrensningene</summary>${listText(MAP.limitations).map(t=>`<p>${escapeHTML(t)}</p>`).join('')}</details><button class="quiet" id="overviewButtonCourse">← Til oversikten</button></header>${pathSelector()}${courseProgress(currentUnit)}<div class="module-grid">${modules().map(m=>{const {units,done,total}=moduleStats(m),next=moduleNext(m),here=moduleFor(currentUnit)?.id===m.id;return `<section class="module-card"><div class="module-head"><div><span class="eyebrow">KURSMODUL · ${escapeHTML((PHASES.find(p=>p.id===m.stage)||{}).title||m.stage||'')}</span><h2>${escapeHTML(m.title||'Modul')}</h2></div>${here?'<span class="here-label">Du er her</span>':''}</div><p>${done} av ${total} øvelser gjort · ${units.filter(u=>completedCount(u)===u.lessons.length).length} av ${units.length} temaer gjort</p><progress value="${done}" max="${total||1}" aria-label="Øvelser gjort i ${escapeHTML(m.title||'modulen')}">${done} av ${total}</progress>${listText(m.goals).length?`<p><strong>Mål:</strong> ${listText(m.goals).map(escapeHTML).join(' · ')}</p>`:''}${listText(m.prerequisites).length?`<p><strong>Forkunnskaper, som veiledning:</strong> ${listText(m.prerequisites).map(escapeHTML).join(' · ')}</p>`:''}${next?`<button class="button-primary" data-lesson="${escapeHTML(next.id)}">Fortsett i modulen →</button>`:''}<details class="module-topics"><summary>Se ${units.length} temaer</summary>${units.map(u=>`<button class="unit-row" data-unit="${escapeHTML(u.id)}"><span class="unit-row-number">${escapeHTML(u.number)}</span><span><strong class="unit-row-title">${escapeHTML(u.title)}</strong><span class="unit-row-goal">${escapeHTML(u.goal)}</span></span><span class="unit-row-progress">${unitStatus(u)} · ${completedCount(u)} / ${u.lessons.length}</span></button>`).join('')}</details>${activityHTML(m)}</section>`;}).join('')}</div>`;}

function renderHome(){const next=suggested(),unit=unitFor(next),lessons=pathLessons(),done=totalDone(),a0=activeUnits().filter(u=>u.stage==='a0'),a0Lessons=a0.flatMap(u=>u.lessons),a0Done=a0Lessons.filter(l=>state.done[l.id]).length,a0Next=a0Suggested(),label=done===lessons.length?'Øv igjen':done||lessons.some(l=>l.id===state.lastByPath[state.selectedPath])?'Fortsett':'Begynn her',stage=(PHASES.find(p=>p.id===unit.stage)||{}).title||unit.level;$('#view').innerHTML=`<section class="home-intro"><div><span class="eyebrow">FRA FØRSTE ORD TIL EGNE TEKSTER</span><h1>Norsk.<br>Litt etter litt.</h1><p>Først et bilde og et ord.<br>Så en setning. Til slutt din egen tekst.</p><div class="home-actions"><button class="button-primary" data-lesson="${next.id}">${label} <span aria-hidden="true">→</span></button><span class="home-next">${escapeHTML(stage)} · ${escapeHTML(unit.title)}<br>${done} av ${lessons.length} øvelser gjort</span><button class="quiet" id="homeHelp">Slik bruker du siden</button></div><div class="a0-start"><button class="quiet" data-lesson="${a0Next.id}">Øv A0 →</button><span>${a0Done} av ${a0Lessons.length} A0-øvelser gjort</span></div></div><div class="cover-illustration">${illustration('book',true)}<p>en bok</p><small>SE · LES · PRØV</small></div></section>${pathSelector()}${courseProgress(unit)}${repeatPanel()}<div class="home-section-head"><h2>${state.selectedPath==='base'?'Grunnløp':'Mer utfordring'}</h2><span>${activeUnits().length} temaer · ${lessons.length} øvelser</span></div><p>Velg blant åpne moduler og temaer i kursoversikten.</p><button class="button-primary" data-course="true">Åpne kursoversikten →</button><p class="home-bottom-note">Start med leksjon 1, eller velg det du vil øve på.</p>`;}

function renderRepeat(){$('#view').innerHTML=`<header class="free-top"><span class="eyebrow">${state.selectedPath==='challenge'?'REPETER KORTE SVAR':'REPETER'}</span><h1>Øv på flere oppgaver først.</h1><p>Prøv minst tre ulike ${state.selectedPath==='challenge'?'korte svar':'ord'} i denne veien før du starter repetisjon. Da kan du møte dem igjen etter andre oppgaver. Du kan også velge den andre veien i oversikten.</p><button class="button-primary" id="backToOverview">Velg en leksjon →</button></header>`;}
function helpControls(){return `<div class="lesson-support">${current.type!=='learn'?`<button class="quiet" id="supportMode">${showModel?'Prøv selv':'Med støtte'}</button>${current.model?`<button class="quiet" id="modelButton">${showModel?'Skjul eksempel':'Vis eksempel'}</button>`:''}<span class="support-status">${assisted?'Hjelp brukt':'Prøv selv · ingen hjelp brukt'}</span>`:''}<label><input type="checkbox" id="translationToggle" ${state.translations?'checked':''}>Ukrainsk og thai</label></div>`;}

function lessonSummary(unit){const done=totalDone(),total=pathLessons().length,phase=PHASES.find(p=>p.id===unit.stage);return `<div class="lesson-summary"><div class="lesson-summary-heading"><strong>${escapeHTML(phase?.title||unit.level)} · Du er her</strong><span>${done} av ${total} øvelser gjort</span></div><progress max="${total}" value="${done}" aria-label="Øvelser gjort i denne veien">${done} av ${total}</progress><small>Viser arbeid, ikke språknivå.</small></div>`;}
function lessonHeader(){const unit=unitFor(),index=unit.lessons.findIndex(l=>l.id===current.id),topic=activeUnits().findIndex(u=>u.id===unit.id)+1,done=completedCount(unit);return `<div class="lesson-meta"><span>${escapeHTML(state.selectedPath==='math'?'Matematikk på norsk':moduleFor(unit)?.title||'')} · LEKSJON ${unit.number} · ${escapeHTML(unit.title.toLocaleUpperCase('nb'))}</span><button class="quiet" id="lessonOverview">Se alle leksjonene</button></div><header class="lesson-header">${state.selectedPath==='math'?'':`<div class="lesson-path"><span>${state.selectedPath==='base'?'Grunnløp':'Mer utfordring'}</span><button class="quiet" data-path="${state.selectedPath==='base'?'challenge':'base'}">Samme tema i ${state.selectedPath==='base'?'Mer utfordring':'Grunnløp'} →</button></div>` }${lessonSummary(unit)}<div class="lesson-course-progress"><strong>Tema ${topic} av ${activeUnits().length} · øvelse ${index+1} av ${unit.lessons.length}</strong><span>${done} av ${unit.lessons.length} øvelser gjort i temaet</span><progress max="${unit.lessons.length}" value="${done}" aria-label="Øvelser gjort i temaet">${done} av ${unit.lessons.length}</progress><small>Viser arbeid, ikke språknivå.</small></div><span class="eyebrow">${repeatMode?(repeatExtra?'EKSTRAØVING':state.selectedPath==='challenge'?'REPETER KORTE SVAR':'REPETER'):escapeHTML(unit.level)}</span><h1>${escapeHTML(current.title)}</h1><p class="instruction">${escapeHTML(current.instruction)}</p>${helpControls()}</header><div class="lesson-progress" aria-label="Øvelser i leksjonen">${unit.lessons.map((l,i)=>`<button class="lesson-step ${state.done[l.id]?'completed':''} ${l.id===current.id?'active':''}" data-lesson="${l.id}" aria-label="Øvelse ${i+1}: ${escapeHTML(l.title)}${state.done[l.id]?', gjort':''}" ${l.id===current.id?'aria-current="step"':''}>${l.type==='learn'?'Lær':l.type==='write'?'Bruk':'Prøv'}</button>`).join('')}<span class="step-count">${index+1} av ${unit.lessons.length}</span></div>`;}
function modelHTML(){if(!current.model||(!showModel&&current.type!=='learn'))return '';return `<div class="model"><span>${current.type==='learn'?'SE OG LES':'EKSEMPEL'}</span><p>${learningText(current.model)}</p></div>`;}
function illustrationGroup(item,decorative=false){const ids=Array.isArray(item.images)&&item.images.length?item.images:item.image?[item.image]:[];return ids.length?`<span class="illustration-group">${ids.map(id=>illustration(id,decorative)).join('')}</span>`:'';}
function renderLesson(){let body=lessonHeader();const type=current.type;if(current.path==='math'&&(type==='learn'||current.unitId==='mat7'))body+=mathReferenceHTML(current.unitId);
 if(type==='learn'){
  body+=modelHTML();if(current.bridge)body+=`<div class="bridges" aria-label="Ord vi kjenner i en ny form">${current.bridge.map(b=>`<div class="bridge">${escapeHTML(b.from)}<span aria-hidden="true">→</span>${escapeHTML(b.to)}</div>`).join('')}</div>`;
  body+=`<div class="word-cards">${current.items.map(item=>`<article class="word-card">${item.image?illustration(item.image):''}<strong>${escapeHTML(item.word)}</strong>${current.path==='math'&&item.meaning?`<span class="math-example">${escapeHTML(item.meaning)}</span>`:''}${state.translations?`<span class="translation" lang="uk">${escapeHTML(item.uk)}</span><span class="translation" lang="th">${escapeHTML(item.th)}</span>`:''}</article>`).join('')}</div><div class="task-actions"><button id="learnDone" class="button-primary">Jeg har øvd →</button></div>`;
 }else{
  body+=modelHTML();
  if(current.prompt)body+=`<section class="reading-note"><small>${current.unitId==='u7'?'BESKJED':'LES'}</small><p>${learningText(current.prompt)}</p></section>`;
  if(current.image||current.images?.length)body+=`<div class="exercise-image">${illustrationGroup(current)}</div>`;
  if(type==='choice')body+=`<div class="choices" aria-label="Velg et svar">${current.options.map((option,i)=>`<button class="choice ${choice===option.id?'selected':''} ${feedback&&choice===option.id?(option.id===current.correct?'correct':'incorrect'):''}" data-choice="${option.id}" aria-pressed="${choice===option.id}" aria-label="${escapeHTML(option.label)}"><span class="choice-marker" aria-hidden="true">${String.fromCharCode(65+i)}</span>${illustrationGroup(option,true)}<span ${current.optionsImageOnly?'class="sr-only"':''}>${escapeHTML(option.label)}</span></button>`).join('')}</div><div class="task-actions"><button id="checkChoice" class="button-primary" ${!choice||submittedCorrect?'disabled':''}>Sjekk svaret →</button><button class="quiet" id="hintButton">${hint?'Skjul hjelp':'Hjelp'}</button></div>`;
  if(type==='build')body+=deskHTML()+`<p class="token-bank-label">KLIKK PÅ ORDBRIKKENE</p><div class="token-bank">${current.tokens.map((text,index)=>({text,index})).filter(t=>!selected.some(s=>s.index===t.index)).map(t=>tokenHTML(t.text,t.index,'bank')).join('')||'<span class="self-note">Alle ordene er på bordet.</span>'}</div><div class="task-actions"><button id="checkBuild" class="button-primary" ${!selected.length||submittedCorrect?'disabled':''}>${current.sentence?'Sjekk setningen':'Sjekk ordene'} →</button><button class="quiet" id="hintButton">${hint?'Skjul hjelp':'Hjelp'}</button></div>`;
  if(type==='input')body+=`<form id="inputForm"><div class="input-exercise ${current.responseLength==='sentence'?'sentence-input':''}"><span>${escapeHTML(current.before||'')}</span><label class="sr-only" for="answerInput">Svaret ditt</label><input id="answerInput" autocomplete="off" autocapitalize="off" spellcheck="false" value="${escapeHTML(inputValue)}" maxlength="100" aria-describedby="inputHint"><span>${escapeHTML(current.after||'')}</span></div><span id="inputHint" class="sr-only">Skriv svaret ditt.</span>${showModel&&current.bank?`<div class="word-bank-help" aria-label="Ord du kan bruke">${current.bank.map(word=>`<span>${escapeHTML(word)}</span>`).join('')}</div>`:''}<div class="task-actions"><button type="submit" class="button-primary" ${!inputValue.trim()||submittedCorrect?'disabled':''}>Sjekk svaret →</button><button type="button" class="quiet" id="hintButton">${hint?'Skjul hjelp':'Hjelp'}</button></div></form>`;
  if(type==='write'){body+=writingHTML();if(current.path==='math')body+=`<aside class="math-partner"><strong>Snakk sammen</strong><p>${escapeHTML(unitFor().talk)}</p></aside>`;}
 }
 if(hint)body+=`<div class="hint" role="note">${escapeHTML(current.hint||'Se eksemplet.')}</div>`;
 body+=feedbackHTML()+(Array.isArray(current.variants)&&current.variants.length?'<div class="task-actions"><button class="quiet" id="newVariant">Prøv en ny variant</button></div>':'')+lessonBottom();$('#view').innerHTML=body;wireInteraction();
}
function tokenHTML(text,index,source){return `<button class="word-token" data-token="${index}" data-source="${source}" draggable="true" aria-label="${source==='board'?'Ta ut':'Legg til'} ${escapeHTML(text)}" title="${source==='board'?'Klikk for å ta ut. Dra for å flytte.':'Klikk for å legge til.'}">${escapeHTML(text)}</button>`;}
function deskHTML(){return `<section class="desk" aria-label="Bygg med ord"><div class="desk-header"><span>${view==='free'?'DINE ORD':'PÅ BORDET'}</span><button id="clearBoard" ${!selected.length?'disabled':''}>Tøm</button></div><div class="sentence" id="sentence" aria-label="Ordene du har valgt">${selected.length?selected.map((token,index)=>tokenHTML(token.text,index,'board')).join('')+(view==='free'||current.sentence?'<span class="period" aria-hidden="true">.</span>':''):'<span class="sentence-empty">Velg ordene under.</span>'}</div></section>`;}
function writingHTML(){const draft=state.drafts[current.id]||{text:'',checks:[]};const short=current.id==='u2l6';return `<section class="write-area"><label class="write-label" for="writingText">${short?'Navnet ditt':'Din tekst'}</label><textarea id="writingText" class="${short?'short':''}" lang="nb" spellcheck="true" placeholder="${escapeHTML(current.placeholder||'Skriv her …')}">${escapeHTML(draft.text)}</textarea><div class="write-tools"><span id="writeCount">${wordCount(draft.text)} ord</span>${state.support&&current.starters?'<button id="insertStarters" class="quiet">Bruk setningsstartere</button>':''}</div><div class="self-checks">${current.checks.map((check,i)=>`<label><input type="checkbox" data-self-check="${i}" ${draft.checks.includes(i)?'checked':''}>${escapeHTML(check)}</label>`).join('')}</div><div class="task-actions"><button id="saveWriting" class="button-primary" ${!canSave(draft)?'disabled':''}>Lagre ${short?'navnet':'teksten'} →</button></div><p class="self-note">${short?'Skriv navnet ditt, og huk av.':'Du sjekker teksten selv. Vis den gjerne til en medelev eller læreren.'}</p></section>`;}
function canSave(draft){return typeof draft.text==='string'&&draft.text.trim().length>0&&!/(\.{3}|…)/.test(draft.text)&&Array.isArray(draft.checks)&&current.checks.every((_,i)=>draft.checks.includes(i));}
function lessonBottom(){if(repeatMode)return `<div class="lesson-bottom"><button class="quiet" id="backToOverview">Til oversikten</button><button class="quiet" id="nextRepeat">Neste oppgave →</button></div>`;const lessons=pathLessons(),index=lessons.findIndex(l=>l.id===current.id);return `<div class="lesson-bottom"><button class="quiet" id="previousLesson" ${index===0?'disabled':''}>← Forrige</button><button class="quiet" id="nextLesson" ${index===lessons.length-1?'disabled':''}>Neste øvelse →</button></div>`;}
function feedbackHTML(){if(!feedback)return '';return `<section class="feedback ${feedback.kind}" role="status"><strong>${escapeHTML(feedback.title)}</strong><p>${escapeHTML(feedback.message)}</p>${feedback.kind==='correct'||feedback.kind==='saved'?nextHTML():''}</section>`;}
function nextHTML(){if(view==='free')return '';if(repeatMode)return `<button id="nextRepeat" class="button-primary">${state.selectedPath==='challenge'?'Neste oppgave':'Neste ord'} →</button>`;const lessons=pathLessons(),index=lessons.findIndex(l=>l.id===current.id);if(index===lessons.length-1)return `<p style="margin-top:12px">${totalDone()===lessons.length?`Du har gjort alle ${lessons.length} øvelsene.`:'Dette er den siste øvelsen. Du kan fortsette å øve i de andre leksjonene.'}</p><button id="backToOverview" class="button-primary">Til oversikten →</button>`;const isLast=unitFor().lessons.at(-1).id===current.id;return `<button id="continueLesson" class="button-primary">${isLast?'Neste leksjon':'Fortsett'} →</button>`;}
function recordDone(answer,self=false){state.done[current.id]={answer,self,kind:current.type};persist();$('#chapterNav').innerHTML=navHTML();}
function success(answer){if(submittedCorrect)return;recordAttempt(true);submittedCorrect=true;recordDone(answer);feedback={kind:'correct',title:'Riktig.',message:current.explanation||answer};renderLesson();announce('Riktig. '+(current.explanation||''));}
function wrong(){recordAttempt(false);assisted=true;const answer=correctForm();feedback={kind:'incorrect',title:'Se på svaret og prøv igjen.',message:`${answer}${/[.!?]$/.test(answer)?'':'.'} ${current.hint||''}`};renderLesson();announce('Se på svaret og prøv igjen. '+answer);}
function nextLesson(){const lessons=pathLessons(),index=lessons.findIndex(l=>l.id===current.id);if(index<lessons.length-1)openLesson(lessons[index+1].id);}
function freeTokens(){return [...FREE_GROUPS.filter(g=>freeCategory==='all'||g.id===freeCategory).flatMap(g=>g.tokens),...(freeCategory==='all'?customTokens:[])];}
function renderFree(){const tokens=freeTokens();$('#view').innerHTML=`<header class="free-top"><span class="eyebrow">ÅPENT VERKSTED</span><h1>Hva vil du skrive?</h1><p>Bygg en setning. Klikk på et ord for å legge det til. Klikk på bordet for å ta det ut.</p></header>${deskHTML()}<div class="task-actions"><button id="saveFree" class="button-primary" ${!selected.length?'disabled':''}>Lagre setningen →</button></div>${feedbackHTML()}<div class="free-categories" aria-label="Velg ord"><button class="free-category ${freeCategory==='all'?'selected':''}" data-category="all" aria-pressed="${freeCategory==='all'}">Alle ord</button>${FREE_GROUPS.map(g=>`<button class="free-category ${freeCategory===g.id?'selected':''}" data-category="${g.id}" aria-pressed="${freeCategory===g.id}">${g.label}</button>`).join('')}</div><div class="token-bank">${tokens.map((token,i)=>tokenHTML(token,i,'bank')).join('')}</div><form class="free-add" id="addWordForm"><label for="customWord">Ditt eget ord eller en kort frase</label><input id="customWord" maxlength="60" required autocomplete="off" placeholder="Et nytt ord …"><button type="submit">Legg til</button></form><p class="self-note">Her er det ingen automatisk fasit. Les setningen sammen med en medelev eller læreren.</p>${state.free.length?`<section class="free-saved"><h2>Dine setninger</h2>${state.free.map((text,i)=>`<div class="saved-line"><p>${escapeHTML(text)}</p><button data-remove-free="${i}" aria-label="Fjern setningen ${escapeHTML(text)}">Fjern</button></div>`).join('')}<button id="copyFree" class="quiet">Kopier setningene</button></section>`:''}`;wireInteraction();$('#addWordForm').addEventListener('submit',e=>{e.preventDefault();const value=$('#customWord').value.trim();if(!value)return;customTokens.push(value);freeCategory='all';renderFree();announce('Ordet er lagt til.');});}
function addToken(index){if(view==='free'){const text=freeTokens()[index];if(!text)return;selected.push({text,index});}else{if(selected.some(t=>t.index===index))return;selected.push({text:current.tokens[index],index});}feedback=null;render();const lastBank=document.querySelector('[data-source="bank"]');if(lastBank)lastBank.focus({preventScroll:true});else $('#checkBuild')?.focus({preventScroll:true});}
function wireInteraction(){const form=$('#inputForm');if(form){form.addEventListener('submit',event=>{event.preventDefault();if(submittedCorrect)return;inputValue=$('#answerInput').value;if(!inputValue.trim())return;if(current.accepted.some(answer=>normalized(answer)===normalized(inputValue)))success((current.before?current.before+' ':'')+inputValue+(current.after&&/^[.!?]/.test(current.after)?current.after:current.after?' '+current.after:''));else wrong();});$('#answerInput').addEventListener('input',event=>{inputValue=event.target.value;form.querySelector('[type="submit"]').disabled=submittedCorrect||!inputValue.trim();if(feedback){feedback=null;$('.feedback')?.remove();}});}
 const textarea=$('#writingText');if(textarea)textarea.addEventListener('input',event=>{const draft=state.drafts[current.id]||{text:'',checks:[]};draft.text=event.target.value;draft.checks=[];state.drafts[current.id]=draft;delete state.done[current.id];feedback=null;persist();$('#chapterNav').innerHTML=navHTML();document.querySelectorAll('[data-self-check]').forEach(check=>check.checked=false);$('#writeCount').textContent=`${wordCount(draft.text)} ord`;$('#saveWriting').disabled=true;$('.feedback')?.remove();});
 const board=$('#sentence');if(!board)return;board.addEventListener('dragover',event=>event.preventDefault());board.addEventListener('drop',event=>{event.preventDefault();let payload;try{payload=JSON.parse(event.dataTransfer.getData('text/plain'));}catch{return;}if(!payload||!Number.isInteger(payload.index))return;const target=event.target.closest('[data-source="board"]');let destination=target?Number(target.dataset.token):selected.length;if(payload.source==='board'){if(!selected[payload.index])return;const [token]=selected.splice(payload.index,1);if(payload.index<destination)destination--;selected.splice(destination,0,token);}else if(payload.source==='bank'){const text=view==='free'?freeTokens()[payload.index]:current.tokens[payload.index];if(!text||view!=='free'&&selected.some(t=>t.index===payload.index))return;selected.splice(destination,0,{text,index:payload.index});}else return;feedback=null;render();});
 document.querySelectorAll('[data-token]').forEach(button=>{button.addEventListener('dragstart',event=>{event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',JSON.stringify({source:button.dataset.source,index:Number(button.dataset.token)}));});if(button.dataset.source==='board')button.addEventListener('keydown',event=>{if(event.altKey&&['ArrowLeft','ArrowRight'].includes(event.key)){event.preventDefault();const index=Number(button.dataset.token),next=index+(event.key==='ArrowLeft'?-1:1);if(next<0||next>=selected.length)return;[selected[index],selected[next]]=[selected[next],selected[index]];feedback=null;render();document.querySelector(`[data-source="board"][data-token="${next}"]`)?.focus({preventScroll:true});}});});
}
function openDialog(label,title,content){$('#dialogLabel').textContent=label;$('#dialogContent').innerHTML=`<h2 id="dialogTitle">${escapeHTML(title)}</h2>${content}`;$('#dialog').showModal();$('#dialog').scrollTop=0;}
function showDictionary(){openDialog('ORDLISTE','Et ord om gangen.','<p>Se ordet på norsk, ukrainsk og thai.</p><input id="dictionarySearch" class="dictionary-search" placeholder="Søk etter et ord …" aria-label="Søk i ordlista"><div class="dictionary-row header"><span>NORSK</span><span>УКРАЇНСЬКА</span><span>ไทย</span></div><div id="dictionaryRows"></div>');renderDictionary('');$('#dictionarySearch').addEventListener('input',event=>renderDictionary(event.target.value));}
function renderDictionary(query){const words=ALL_WORDS.filter(item=>[item.word,item.uk,item.th,item.meaning].join(' ').toLocaleLowerCase().includes(query.trim().toLocaleLowerCase()));$('#dictionaryRows').innerHTML=words.length?words.map(item=>`<div class="dictionary-row"><div><strong>${escapeHTML(item.word)}</strong><small>${escapeHTML(item.meaning)}</small></div><div lang="uk">${escapeHTML(item.uk)}</div><div lang="th">${escapeHTML(item.th)}</div></div>`).join(''):'<p>Ingen treff. Prøv et kortere ord.</p>';}
function archivedAnswer(entry){const record=entry?.record;return typeof record?.answer==='string'?record.answer:record?.answer==null?'':String(record.answer);}
function workbookText(){const sections=Object.keys(pathLabels).map(path=>{const units=ALL_UNITS.filter(u=>u.path===path);const lines=units.flatMap(unit=>unit.lessons.filter(l=>state.done[l.id]||state.drafts[l.id]?.text?.trim()).map(l=>{const done=state.done[l.id],draft=state.drafts[l.id]?.text;return `${unit.number} · ${unit.title} · ${l.title}\n${done?.answer||draft||''}${done&&draft&&draft!==done.answer?'\nUtkast: '+draft:''}`;}));return `${pathLabels[path]}\n${lines.join('\n\n')}`;});return sections.join('\n\n')+(state.free.length?'\n\nEgne setninger\n'+state.free.join('\n'):'')+(state.archivedDone.length?'\n\nTidligere arbeid før oppdateringen\n'+state.archivedDone.map(entry=>`${entry?.id||''}: ${archivedAnswer(entry)}`).join('\n'):'')+(legacyTexts().length?'\n\nTidligere tekster\n'+legacyTexts().join('\n\n'):'');}

function legacyTexts(){if(!oldWork||typeof oldWork!=='object')return [];const drafts=Object.values(oldWork.drafts||{}).filter(d=>d&&typeof d.text==='string'&&d.text.trim()).map(d=>d.text);const free=Array.isArray(oldWork.free)?oldWork.free.filter(s=>typeof s==='string'):[];return [...drafts,...free];}
function legacyHTML(){const texts=legacyTexts();return texts.length?`<details><summary>Tidligere tekster</summary><p>Fra den første versjonen av Språkverkstedet. Disse teller ikke som øvelser i det nye løpet.</p>${texts.map(text=>`<div class="workbook-entry"><p>${escapeHTML(text)}</p></div>`).join('')}</details>`:'';}
function learningLabels(lesson){const names={recognition:'kjenne igjen',recall:'hente fram',construction:'bygge',reading:'lese'},statuses={practicing:'øver',supported:'med hjelp',independent:'selvstendig nå',remembered:'husket senere'};return Object.values(state.learning.records).filter(r=>r.lessonId===lesson.id&&statuses[r.status]).map(r=>`${names[r.skill]||r.skill}: ${statuses[r.status]}`).join(' · ');}
function archivedDoneHTML(){return state.archivedDone.length?`<details><summary>Tidligere arbeid før oppdateringen</summary><p>Disse svarene er beholdt fra oppgaver som er endret, og teller ikke som fullført i det nye løpet.</p>${state.archivedDone.map(entry=>`<div class="workbook-entry"><small>${escapeHTML(entry?.id)} · ${escapeHTML(entry?.record?.kind||'tidligere oppgave')}</small><p>${escapeHTML(archivedAnswer(entry))}</p></div>`).join('')}</details>`:'';}
function showWorkbook(){const any=ALL_LESSONS.some(l=>state.done[l.id]||state.drafts[l.id]?.text?.trim())||state.free.length||state.archivedDone.length||legacyTexts().length;openDialog('MIN ARBEIDSBOK','Det du har øvd på.',`<p>Her finner du arbeidet ditt fra norskkurset og matematikksporet. Forsøk med og uten hjelp vises separat. Antall fullførte øvelser er ikke en nivåprøve. Tekstene lagres i denne nettleseren.</p><div class="workbook-tools"><button id="copyWorkbook" ${!any?'disabled':''}>Kopier arbeidet</button><button id="downloadWorkbook" ${!any?'disabled':''}>Last ned som tekst</button></div>${[state.selectedPath,...Object.keys(pathLabels).filter(p=>p!==state.selectedPath)].map(path=>`<h2>${pathLabels[path]}</h2>${ALL_UNITS.filter(u=>u.path===path).map(unit=>`<section class="workbook-unit"><h3>${unit.number} · ${escapeHTML(unit.title)}</h3>${unit.lessons.map(lesson=>{const done=state.done[lesson.id],draft=state.drafts[lesson.id]?.text;return done?`<div class="workbook-entry"><small>✓ ${escapeHTML(lesson.title)} · ${done.self?'EGENVURDERT':done.kind==='learn'?'SETT OG LEST':escapeHTML(learningLabels(lesson)||'TIDLIGERE ARBEID')}</small><p>${escapeHTML(done.answer)}</p>${draft&&draft!==done.answer?`<p>Utkast: ${escapeHTML(draft)}</p>`:''}</div>`:draft?`<div class="workbook-entry"><small>${escapeHTML(lesson.title)} · UTKAST</small><p>${escapeHTML(draft)}</p></div>`:`<div class="workbook-entry pending">${escapeHTML(lesson.title)}</div>`;}).join('')}</section>`).join('')}`).join('')}${state.free.length?`<h3>Egne setninger</h3>${state.free.map(text=>`<div class="workbook-entry"><p>${escapeHTML(text)}</p></div>`).join('')}`:''}${archivedDoneHTML()}${legacyHTML()}`);}

function showHelp(){openDialog('HJELP','Ett lite steg om gangen.','<ol><li>Velg en leksjon. Begynn gjerne med «Ord rundt meg».</li><li>Se på bildene. Les ordet eller setningen.</li><li>Velg et svar, bygg med ord eller skriv selv.</li><li>Trykk «Sjekk svaret». Prøv igjen hvis du trenger det.</li><li>Trykk «Fortsett» for neste øvelse.</li></ol><p>Velg «Vis eksempel» eller «Med støtte» når du vil ha hjelp. Når du bruker hjelp, vises det ved oppgaven. Bruk ordlista når et ord er ukjent. Du kan gjøre øvelsene flere ganger.</p><p>Bygg med mus, berøring eller tastatur. Trykk Tab og Enter for å velge ord. Klikk på et ord på bordet for å ta det ut. Du kan også dra ordene, eller flytte et valgt ord med Alt + venstre/høyre pil.</p><p>Arbeidet ditt lagres i denne nettleseren. Ingen nedtelling.</p>');}
function showTeacher(){const count=stage=>{const units=BASE_UNITS.filter(u=>u.stage===stage);return `${units.length} leksjoner · ${units.reduce((n,u)=>n+u.lessons.length,0)} øvelser`;};openDialog('TIL LÆREREN','Fra første ord til korte tekster.',`<p>Dette er et avgrenset, visuelt øvingsløp i lesing og skriving for ungdom og voksne som er nye i norsk. Hver vei har ${BASE_UNITS.length} leksjoner. Grunnløpet har ${BASE_UNITS.reduce((n,u)=>n+u.lessons.length,0)} øvelser og Mer utfordring har ${MORE_UNITS.reduce((n,u)=>n+u.lessons.length,0)} øvelser.</p><table class="teacher-table"><thead><tr><th>Del</th><th>Innhold</th><th>Arbeidsmåte</th></tr></thead><tbody><tr><td>A0<br>${count('a0')}</td><td>Kjente ting → Her er / Jeg har → tall, farger og størrelse → handlinger → repetisjon</td><td>Se, lese, velge og skrive i små steg</td></tr><tr><td>På vei<br>${count('bridge')}</td><td>Ord blir korte setninger</td><td>Bygge, fullføre og skrive med støtte</td></tr><tr><td>A1<br>${count('a1')}</td><td>Hverdag, planer og korte tekster</td><td>Lese og bruke kjent språk</td></tr><tr><td>Videre · mot A2<br>${count('a1plus')}</td><td>Flere situasjoner og lengre sammenhenger</td><td>Lese og skrive med støtte ved behov</td></tr><tr><td>A2 · grunnlag<br>${count('a2')}</td><td>Språk i flere hverdagssituasjoner</td><td>Lesing og korte tekster</td></tr><tr><td>A2 · videre<br>${count('a2plus')}</td><td>Mer sammenheng og variasjon</td><td>Lesing og skriving med støtte</td></tr><tr><td>Mot B1<br>${count('b1')}</td><td>Mer sammenhengende språkbruk</td><td>Lesing og skriving i kontekst</td></tr></tbody></table><h3>Klasseromsaktiviteter</h3><p>I hver modul finnes en frivillig lærerledet aktivitet med forslag til instruksjon og lærerskript. Elevenes egenregistrering lagres separat fra øvelser og mestring; den er ikke en vurdering av lytting eller uttale.</p><h3>Velg og bytt vei</h3><p>Grunnløpet gir små steg og øving. Mer utfordring bruker flere opplysninger, oppgaver der eleven retter avvik, og egne korte svar. Velg vei etter hva eleven vil øve på, og bytt til samme tema underveis. Støtte og eksempler er tilgjengelige i begge veier.</p><h3>Modell, valg, egen bruk</h3><p>Gjør den første øvelsen sammen. La eleven peke, velge og lese før eleven skriver. Bruk ordene om igjen med ting i rommet. Modellen vises i læreoppgaver. I andre øvelser begynner eleven uten eksempel og kan velge støtte. Hjelp registreres også når eleven går videre uten å svare. Feil registreres ved forsøket. Leksjonsoversikten er åpen, så du kan tilpasse rekkefølgen.</p><div class="dialog-note"><p style="margin:0">A0 brukes her som en pedagogisk startbetegnelse. Europarådet bruker Pre-A1 om nivået før A1. Gjennomførte øvelser viser arbeid med disse oppgavene, og dokumenterer ikke oppnådd språknivå. Nettstedet spiller ikke av lyd eller vurderer muntlig språk; valgfrie lærerledede aktiviteter kan gi mulighet for lytting og samtale i klassen.</p></div><h3>Hva blir vurdert?</h3><p>Avgrensede ord-, valg- og byggeoppgaver har fasit. Navn og frie tekster lagres med elevens egenkontroll. De får ingen automatisk grammatisk godkjenning. La en medelev eller lærer lese de frie tekstene.</p><h3>Språkstøtte</h3><p>Ordkort og ordliste har ukrainsk og thai. Oversettelsene er kontekststøtte, ikke ord-for-ord-fasit for hele språkets bruk.</p><h3>Lagring og videre arbeid</h3><p>Arbeidsboka lagres på denne enheten, uten innsending eller felles læreroversikt. Kopier eller last ned arbeidet som tekst ved behov. Tekster fra første versjon er beholdt i «Tidligere tekster» og teller ikke som fullførte oppgaver i dette løpet.</p><p>Kilde for nivåorientering: <a href="https://rm.coe.int/common-european-framework-of-reference-for-languages-learning-teaching/16809ea0d4" target="_blank" rel="noopener">Europarådet, CEFR Companion volume (2020)</a>, særlig s. 54, 66 og 243. Leksjonene og øvelsene er en pedagogisk tilpasning.</p><button id="researchButton">Forskningsgrunnlag</button> <button id="printLesson">Skriv ut den åpne øvelsen</button>`);}

function showResearch(){const sources=Array.isArray(MAP.sources)?MAP.sources:[],mapping=modules().map(m=>({module:m,links:Array.isArray(m.curriculumLinks)?m.curriculumLinks:[]}));const sourceList=sources.map(source=>{const title=escapeHTML(source.title||source.id||'Kilde'),url=typeof source.url==='string'&&/^https?:\/\//i.test(source.url)?source.url:'';return `<p>${url?`<a href="${escapeHTML(url)}" target="_blank" rel="noopener">${title}</a>`:title}${source.kind?` · ${escapeHTML(source.kind)}`:''}${source.checkedDate?` · kontrollert ${escapeHTML(source.checkedDate)}`:''}<br>${escapeHTML(source.application||'')}${source.limitation?` ${escapeHTML(source.limitation)}`:''}</p>`;}).join('');openDialog('FORSKNING OG LÆREPLAN','Grunnlag og avgrensninger.',`<h3>Læreplaner og veiledninger</h3><p>NOR07-03 er læreplanen for norsk for språklige minoriteter i videregående opplæring. FOV og HK-dir er referanser for andre opplæringsløp. Kursmodulene er våre egne pedagogiske grupper, ikke FOVs offisielle moduler eller en nivåvurdering. De bruker kildene som pedagogiske delmål; de erstatter ikke den gjeldende læreplanen eller dokumenterer oppnådd nivå.</p>${sourceList}<h3>Modulene og målene</h3>${mapping.map(({module,links})=>`<p><strong>${escapeHTML(module.title||'Modul')}</strong>${links.length?'<br>'+links.map(link=>{const source=sources.find(x=>x.id===link.sourceId);return `${escapeHTML(source?.title||link.sourceId)}: ${escapeHTML(link.targetSummary)} (${link.coverage==='teacher-led'?'lærerledet':'delvis dekket'})`;}).join('<br>'):'<br>Ingen tilknytning oppgitt.'}</p>`).join('')}<h3>Avgrensninger</h3>${listText(MAP.limitations).map(t=>`<p>${escapeHTML(t)}</p>`).join('')}<h3>Forskningsgrunnlag</h3>${EVIDENCE.principles.map(p=>`<h4>${escapeHTML(p.title)}</h4><p>${escapeHTML(p.practice)}</p>`).join('')}<p>${escapeHTML(EVIDENCE.limits)}</p><h3>Forskningskilder</h3>${EVIDENCE.sources.map(source=>`<p><a href="${escapeHTML(source.url)}" target="_blank" rel="noopener">${escapeHTML(source.authors)} (${source.year}): ${escapeHTML(source.title)}</a><br>${escapeHTML(source.finding)} ${escapeHTML(source.limits)}</p>`).join('')}`);}

async function copyText(text){try{await navigator.clipboard.writeText(text);announce('Teksten er kopiert.');const button=$('#copyWorkbook')||$('#copyFree');if(button)button.textContent='Kopiert';}catch{openDialog('KOPIER TEKST','Arbeidet ditt',`<p>Marker og kopier teksten under.</p><textarea class="dictionary-search" rows="12" readonly aria-label="Tekst du kan kopiere">${escapeHTML(text)}</textarea>`);}}
function downloadText(){const text=workbookText();const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='Min_arbeidsbok_norsk.txt';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function setDraftChecks(index,checked){const draft=state.drafts[current.id]||{text:'',checks:[]};draft.checks=draft.checks.filter(i=>i!==index);if(checked)draft.checks.push(index);state.drafts[current.id]=draft;persist();$('#saveWriting').disabled=!canSave(draft);}
function delegatedClick(event){const button=event.target.closest('button');if(!button||button.disabled)return;
 if(button.dataset.math){openMath();return;}
 if(button.dataset.course){openCourse();return;}
 if(button.dataset.repeat){startRepeat();return;}
 if(button.dataset.path){switchPath(button.dataset.path);return;}
 if(button.dataset.unit){const unit=ALL_UNITS.find(u=>u.id===button.dataset.unit);openLesson((unit.lessons.find(l=>!state.done[l.id])||unit.lessons[0]).id);return;}
 if(button.dataset.lesson){openLesson(button.dataset.lesson);return;}
 if(button.dataset.choice){if(submittedCorrect)return;choice=button.dataset.choice;feedback=null;renderLesson();document.querySelector(`[data-choice="${choice}"]`)?.focus({preventScroll:true});return;}
 if(button.dataset.token!==undefined){if(submittedCorrect&&view==='lesson')return;const index=Number(button.dataset.token);if(button.dataset.source==='bank')addToken(index);else{selected.splice(index,1);feedback=null;render();$('#sentence')?.querySelector('button')?.focus({preventScroll:true});}return;}
 if(button.dataset.category){freeCategory=button.dataset.category;renderFree();return;}
 if(button.dataset.removeFree!==undefined){state.free.splice(Number(button.dataset.removeFree),1);persist();renderFree();return;}
 switch(button.id){
 case 'lessonOverview':case 'backToOverview':if(state.selectedPath==='math'){openMath();break;}openHome();break;
 case 'overviewButton':case 'overviewButtonCourse':openHome();break;
 case 'homeHelp':case 'helpButton':showHelp();break;
 case 'dictionaryButton':if(view==='lesson'&&current.type!=='learn'){markAssisted();renderLesson();}showDictionary();break;
 case 'workbookButton':showWorkbook();break;
 case 'teacherButton':showTeacher();break;
 case 'researchButton':showResearch();break;
 case 'closeDialog':$('#dialog').close();break;
 case 'learnDone':recordDone(current.model||current.items.map(item=>item.word).join(' · '));feedback={kind:'correct',title:'Du har øvd.',message:'Les ordene en gang til, eller gå videre.'};renderLesson();announce('Du har øvd.');break;
 case 'checkChoice':if(submittedCorrect)break;if(choice===current.correct)success(current.options.find(option=>option.id===choice).label);else wrong();break;
 case 'checkBuild':if(submittedCorrect)break;if(normalized(textOfTokens())===normalized(current.answer.join(' ')))success(textOfTokens());else wrong();break;
 case 'hintButton':hint=!hint;if(hint)markAssisted();renderLesson();break;
 case 'modelButton':case 'supportMode':showModel=!showModel;if(showModel){markAssisted();if(!current.model&&!current.bank)hint=true;}renderLesson();break;
 case 'repeatButton':startRepeat();break;
 case 'nextRepeat':nextRepeat();break;
 case 'newVariant':{const base=ALL_LESSONS.find(l=>l.id===current.id);repeatMode=false;openLesson(base.id);break;}
 case 'clearBoard':selected=[];feedback=null;render();break;
 case 'continueLesson':case 'nextLesson':nextLesson();break;
 case 'previousLesson':{const lessons=pathLessons(),index=lessons.findIndex(l=>l.id===current.id);if(index>0)openLesson(lessons[index-1].id);break;}
 case 'insertStarters':{markAssisted();const draft=state.drafts[current.id]||{text:'',checks:[]};if(draft.text.trim()){announce('Du har allerede skrevet. Bruk eksemplet over.');break;}draft.text=current.starters;draft.checks=[];state.drafts[current.id]=draft;persist();renderLesson();$('#writingText').focus();break;}
 case 'saveWriting':{const draft=state.drafts[current.id];if(!canSave(draft))break;recordDone(draft.text,true);feedback={kind:'saved',title:current.id==='u2l6'?'Navnet er lagret.':'Lagret med egenvurdering.',message:current.explanation};renderLesson();announce(feedback.title);break;}
 case 'freeButton':openFree();break;
 case 'saveFree':{const text=textOfTokens();if(!state.free.includes(text)){state.free.unshift(text);state.free=state.free.slice(0,60);persist();}feedback={kind:'info',title:'Setningen er lagret.',message:'Les den sammen med en medelev eller læreren. Gir setningen mening?'};renderFree();announce('Setningen er lagret.');break;}
 case 'copyFree':copyText(state.free.join('\n'));break;
 case 'copyWorkbook':copyText(workbookText());break;
 case 'downloadWorkbook':downloadText();break;
 case 'printLesson':$('#dialog').close();window.print();break;
 }
}
function restoreRoute(){const id=location.hash.slice(1);if(ALL_LESSONS.some(l=>l.id===id))openLesson(id,{route:false,focus:false});else if(id==='matematikk')openMath(false);else if(id==='fri'){leaveMath();openFree(false);}else if(id==='kurs')openCourse(false);else {if(id==='utfordring'||id==='oversikt'){state.selectedPath=id==='utfordring'?'challenge':'base';persist();}openHome(false);}}
$('#homeLink').addEventListener('click',event=>{event.preventDefault();openHome();});
 document.addEventListener('click',delegatedClick);
 document.addEventListener('change',event=>{if(event.target.id==='supportToggle'){state.support=event.target.checked;persist();renderLesson();}else if(event.target.id==='translationToggle'){state.translations=event.target.checked;persist();renderLesson();}else if(event.target.dataset.activity!==undefined){state.activities[event.target.dataset.activity]=event.target.checked;persist();}else if(event.target.dataset.selfCheck!==undefined)setDraftChecks(Number(event.target.dataset.selfCheck),event.target.checked);});
 $('#dialog').addEventListener('click',event=>{if(event.target===$('#dialog')){const rect=$('#dialog').getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)$('#dialog').close();}});
 window.addEventListener('popstate',restoreRoute);
 const mobile=matchMedia('(max-width:780px)');$('#chapterMenu').open=!mobile.matches;mobile.addEventListener('change',event=>$('#chapterMenu').open=!event.matches);
 if(!canStore)storageNotice();restoreRoute();
